function histogram(test) {
    const letterCounts = {};
    const letters = test.split(" ").filter(letter => letter !== "");

    letters.forEach(letter => {
        if (letterCounts[letter]) {
            letterCounts[letter]++;
        } else {
            letterCounts[letter] = 1;
        }
    });

    let maxCount = 0;
    Object.values(letterCounts).forEach(count => {
        if (count > maxCount) {
            maxCount = count;
        }
    });

    const result = {};
    Object.keys(letterCounts).forEach(letter => {
        if (letterCounts[letter] === maxCount) {
            result[letter] = maxCount;
        }
    });

    return result;
}
```

