function reverse_delete(s, c) {
    // Create a set of characters to be deleted for quick lookup
    const deleteSet = new Set(c.split(''));

    // Filter out characters in s that are in deleteSet
    let result = s.split('').filter(char => !deleteSet.has(char)).join('');

    // Check if the result string is a palindrome
    let isPalindrome = result === result.split('').reverse().join('');

    // Return the result string and the palindrome check
    return [result, isPalindrome];
}
```

