    if (isGood(second + first)) {
        return "Yes";
    }

    return "No";
}

function isGood(s) {
    let balance = 0;
    for (let char of s) {
        if (char === '(') {
            balance++;
        } else if (char === ')') {
            balance--;
            if (balance < 0) {
                return false;
            }
        }
    }
    return balance === 0;
}
