        { value: 10, symbol: 'x' },
        { value: 9, symbol: 'ix' },
        { value: 5, symbol: 'v' },
        { value: 4, symbol: 'iv' },
        { value: 1, symbol: 'i' }
    ];

    let roman = '';

    for (let i = 0; i < romanNumerals.length; i++) {
        while (number >= romanNumerals[i].value) {
            roman += romanNumerals[i].symbol;
            number -= romanNumerals[i].value;
        }
    }

    return roman;
}
