function sort_numbers(numbers){
    const numberMap = {
        zero: 0,
        one: 1,
        two: 2,
        three: 3,
        four: 4,
        five: 5,
        six: 6,
        seven: 7,
        eight: 8,
        nine: 9
    };

    const sortedNumbers = numbers.split(' ')
                                .map(num => numberMap[num])
                                .sort((a, b) => a - b)
                                .map(num => Object.keys(numberMap).find(key => numberMap[key] === num));

    return sortedNumbers.join(' ');
}
