function parse_nested_parens(paren_string) {
    const groups = paren_string.split(' ');
    const depths = groups.map(group => {
        let maxDepth = 0;
        let currentDepth = 0;
        for (let char of group) {
            if (char === '(') {
                currentDepth++;
                if (currentDepth > maxDepth) {
                    maxDepth = currentDepth;
                }
            } else if (char === ')') {
                currentDepth--;
            }
        }
        return maxDepth;
    });
    return depths;
}
```

