function search(arr) {
    let left = 0;
    let right = arr.length - 1;

    while (left < right) {
        let mid = left + Math.floor((right - left) / 2);

        // Check if the mid is at the unique element
        if (mid % 2 === 1) {
            mid--;
        }

        // If the pair is not equal, the unique element is on the left side
        if (arr[mid] !== arr[mid + 1]) {
            right = mid;
        } else {
            // If the pair is equal, the unique element is on the right side
            left = mid + 2;
        }
    }

    // When left == right, we have found the unique element
    return arr[left];
}
