function max_sum(arr) {
    let n = arr.length;
    let inc = new Array(n).fill(0);
    let dec = new Array(n).fill(0);

    // Calculate maximum sum increasing subsequence for each element
    for (let i = 0; i < n; i++) {
        inc[i] = arr[i];
        for (let j = 0; j < i; j++) {
            if (arr[i] > arr[j] && inc[i] < inc[j] + arr[i]) {
                inc[i] = inc[j] + arr[i];
            }
        }
    }

    // Calculate maximum sum decreasing subsequence for each element
    for (let i = n - 1; i >= 0; i--) {
        dec[i] = arr[i];
        for (let j = n - 1; j > i; j--) {
            if (arr[i] > arr[j] && dec[i] < dec[j] + arr[i]) {
                dec[i] = dec[j] + arr[i];
            }
        }
    }

    // Find the maximum sum of bitonic subsequence
    let maxSum = 0;
    for (let i = 0; i < n; i++) {
        maxSum = Math.max(maxSum, inc[i] + dec[i] - arr[i]);
    }

    return maxSum;
}
```

