function count_no_of_ways(n, k) {
    if (n === 0) return 0;
    if (n === 1) return k;

    let mod = 1000000007;
    let same = k;
    let diff = k * (k - 1);
    let total = same + diff;

    for (let i = 3; i <= n; i++) {
        same = diff;
        diff = total * (k - 1);
        total = (same + diff) % mod;
    }

    return total;
}
```

