function pancake_sort(nums) {
    function flip(subarr, k) {
        let start = 0;
        while (start < k) {
            let temp = subarr[start];
            subarr[start] = subarr[k];
            subarr[k] = temp;
            start++;
            k--;
        }
    }

    let n = nums.length;
    for (let curr_size = n; curr_size > 1; --curr_size) {
        // Find index of the maximum element in nums[0..curr_size-1]
        let mi = nums.indexOf(Math.max(...nums.slice(0, curr_size)));

        // Move the maximum number to end of current array if it's not already at the end
        if (mi != curr_size - 1) {
            // First move the maximum number to beginning
            flip(nums, mi);
            // Now move the maximum number to end by reversing current array
            flip(nums, curr_size - 1);
        }
    }
    return nums;
}
