function comb_sort(nums) {
    let gap = nums.length;
    let shrinkFactor = 1.3;
    let sorted = false;

    while (!sorted) {
        gap = Math.floor(gap / shrinkFactor);
        if (gap <= 1) {
            gap = 1;
            sorted = true;
        }

        for (let i = 0; i + gap < nums.length; i++) {
            if (nums[i] > nums[i + gap]) {
                let temp = nums[i];
                nums[i] = nums[i + gap];
                nums[i + gap] = temp;
                sorted = false;
            }
        }
    }

    return nums;
}
```

