std::map<std::string,long> histogram(std::string test) {
    std::map<std::string, long> letterCounts;
    std::istringstream iss(test);
    std::string letter;
    while (iss >> letter) {
        letterCounts[letter]++;
    }
    long maxCount = 0;
    for (const auto& pair : letterCounts) {
        if (pair.second > maxCount) {
            maxCount = pair.second;
        }
    }
    std::map<std::string, long> result;
    for (const auto& pair : letterCounts) {
        if (pair.second == maxCount) {
            result.insert(pair);
        }
    }
    return result;
}
