std::tuple<std::string, bool> reverse_delete(std::string s, std::string c) {
    std::unordered_set<char> chars_to_delete(c.begin(), c.end());
    std::string result;
    for (char ch : s) {
        if (chars_to_delete.find(ch) == chars_to_delete.end()) {
            result += ch;
        }
    }
    std::string reversed_result(result.rbegin(), result.rend());
    bool is_palindrome = result == reversed_result;
    return std::make_tuple(result, is_palindrome);
}
