    double shrink_factor = 1.3;
    long gap = nums.size();
    bool swapped = true;

    while (gap > 1 || swapped) {
        if (gap > 1) {
            gap = static_cast<long>(gap / shrink_factor);
        }

        swapped = false;

        for (long i = 0; i + gap < nums.size(); ++i) {
            if (nums[i] > nums[i + gap]) {
                std::swap(nums[i], nums[i + gap]);
