    long n = my_list.size();
    for (long gap = n / 2; gap > 0; gap /= 2) {
        for (long i = gap; i < n; i += 1) {
            long temp = my_list[i];
            long j;
            for (j = i; j >= gap && my_list[j - gap] > temp; j -= gap) {
                my_list[j] = my_list[j - gap];
