long max_sum(std::vector<long> arr) {
    int n = arr.size();
    vector<long> inc(n), dec(n);

    // Calculate maximum sum increasing subsequence for each element
    for (int i = 0; i < n; i++) {
        inc[i] = arr[i];
        for (int j = 0; j < i; j++) {
            if (arr[i] > arr[j] && inc[i] < inc[j] + arr[i]) {
                inc[i] = inc[j] + arr[i];
            }
        }
