    // Calculate maximum sum decreasing subsequence for each element
    for (int i = n - 1; i >= 0; i--) {
        dec[i] = arr[i];
        for (int j = n - 1; j > i; j--) {
            if (arr[i] > arr[j] && dec[i] < dec[j] + arr[i]) {
                dec[i] = dec[j] + arr[i];
            }
        }
    }

    // Find the maximum sum of bitonic subsequence
    long max_bitonic_sum = 0;
    for (int i = 0; i < n; i++) {
        max_bitonic_sum = max(max_bitonic_sum, inc[i] + dec[i] - arr[i]);
    }

    return max_bitonic_sum;
}
