fn separate_paren_groups(paren_string: String) -> Vec<String> {
    let mut result = Vec::new();
    let mut current_group = String::new();
    let mut depth = 0;

    for c in paren_string.chars().filter(|c| !c.is_whitespace()) {
        current_group.push(c);
        if c == '(' {
            depth += 1;
        } else if c == ')' {
            depth -= 1;
