fn decimal_to_binary(decimal: isize) -> String {
    if decimal == 0 {
        return String::from("db0db");
    }
    let mut binary = String::new();
    let mut num = decimal;
    while num > 0 {
        binary = format!("{}{}", num % 2, binary);
        num /= 2;
    }
    format!("db{}db", binary)
}
```

