fn sort_array(array: Vec<isize>) -> Vec<isize> {
    let mut sorted_array = array.clone();
    if sorted_array.is_empty() {
        return sorted_array;
    }
    let sum = sorted_array.first().unwrap() + sorted_array.last().unwrap();
    if sum % 2 == 0 {
        sorted_array.sort_by(|a, b| b.cmp(a));
    } else {
        sorted_array.sort();
    }
    sorted_array
}
