fn pancake_sort(nums: Vec<isize>) -> Vec<isize> {
    let mut nums = nums;
    let mut size = nums.len();

    while size > 1 {
        // Find the index of the maximum element in nums[0..size]
        let max_index = nums[0..size].iter().enumerate().max_by_key(|&(_, &x)| x).unwrap().0;

        if max_index != size - 1 {
            // Flip the array from 0 to max_index
            nums[0..=max_index].reverse();
            // Flip the array from 0 to size-1
            nums[0..size].reverse();
        }

        size -= 1;
    }

    nums
}
```

