fn factorize(n: isize) -> Vec<isize> {
    let mut factors = Vec::new();
    let mut number = n;

    // Factor out powers of 2
    while number % 2 == 0 {
        factors.push(2);
        number /= 2;
    }

    // Factor out other primes
    let mut factor = 3;
    while factor * factor <= number {
        while number % factor == 0 {
            factors.push(factor);
            number /= factor;
        }
        factor += 2;
    }

    // If number is a prime greater than 2
    if number > 2 {
        factors.push(number);
    }

    factors
}
