fn lps(str: String) -> isize {
    let s: Vec<char> = str.chars().collect();
    let n = s.len();
    let mut dp = vec![vec![0; n]; n];

    for i in 0..n {
        dp[i][i] = 1;
    }

    for cl in 2..=n {
        for i in 0..=n - cl {
            let j = i + cl - 1;
            if s[i] == s[j] && cl == 2 {
                dp[i][j] = 2;
            } else if s[i] == s[j] {
                dp[i][j] = dp[i + 1][j - 1] + 2;
            } else {
                dp[i][j] = dp[i][j - 1].max(dp[i + 1][j]);
            }
        }
    }

    dp[0][n - 1]
}
