fn max_sum(arr: Vec<isize>) -> isize {
    let n = arr.len();
    if n == 0 {
        return 0;
    }

    let mut inc = vec![0; n];
    let mut dec = vec![0; n];

    for i in 0..n {
        inc[i] = arr[i];
        dec[i] = arr[i];
    }

    for i in 1..n {
        for j in 0..i {
            if arr[i] > arr[j] && inc[i] < inc[j] + arr[i] {
                inc[i] = inc[j] + arr[i];
            }
        }
    }

    for i in (0..n-1).rev() {
        for j in (i+1)..n {
            if arr[i] > arr[j] && dec[i] < dec[j] + arr[i] {
                dec[i] = dec[j] + arr[i];
            }
        }
    }

    let mut max_sum = 0;
    for i in 0..n {
        max_sum = max_sum.max(inc[i] + dec[i] - arr[i]);
    }

    max_sum
}
```

