fn generate_combinations(l: &Vec<String>, n: isize, start: usize, current_combination: &mut Vec<String>, result: &mut Vec<Vec<String>>) {
    if current_combination.len() as isize == n {
        result.push(current_combination.clone());
        return;
    }
    for i in start..l.len() {
        current_combination.push(l[i].clone());
        generate_combinations(l, n, i, current_combination, result);
        current_combination.pop();
    }
}
