fn count_no_of_ways(n: isize, k: isize) -> isize {
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return k;
    }
    let mut mod_val = 1000000007;
    let mut same = k;
    let mut diff = k * (k - 1);
    let mut total = same + diff;
    for _ in 2..n {
        same = diff;
        diff = total * (k - 1) % mod_val;
        total = (same + diff) % mod_val;
    }
    total
}
