fn shell_sort(my_list: Vec<isize>) -> Vec<isize> {
    let mut list = my_list.clone();
    let mut gap = list.len() / 2;

    while gap > 0 {
        for i in gap..list.len() {
            let temp = list[i];
            let mut j = i;

            while j >= gap && list[j - gap] > temp {
                list[j] = list[j - gap];
                j -= gap;
            }

            list[j] = temp;
        }

        gap /= 2;
    }

    list
}
```

