fn int_to_mini_roman(number: isize) -> String {
    let mut number = number;
    let mut roman = String::new();
    let roman_numerals = [
        (1000, "m"),
        (900, "cm"),
        (500, "d"),
        (400, "cd"),
        (100, "c"),
        (90, "xc"),
        (50, "l"),
        (40, "xl"),
        (10, "x"),
        (9, "ix"),
        (5, "v"),
        (4, "iv"),
        (1, "i"),
    ];

    for &(value, numeral) in roman_numerals.iter() {
        while number >= value {
            roman.push_str(numeral);
            number -= value;
        }
    }

    roman
}
