fn solve(s: String) -> String {
    let mut has_letters = false;
    let mut result = String::new();

    for c in s.chars() {
        if c.is_alphabetic() {
            has_letters = true;
            if c.is_lowercase() {
                result.push(c.to_ascii_uppercase());
            } else {
                result.push(c.to_ascii_lowercase());
            }
        } else {
            result.push(c);
        }
    }

    if !has_letters {
        return result.chars().rev().collect();
    }

    result
}
```

