fn remove_duplicates(numbers: Vec<isize>) -> Vec<isize> {
    let mut occurrences = HashMap::new();
    let mut result = Vec::new();

    for &number in &numbers {
        *occurrences.entry(number).or_insert(0) += 1;
    }

