fn comb_sort(nums: Vec<isize>) -> Vec<isize> {
    let mut nums = nums;
    let mut gap = nums.len();
    let shrink_factor = 1.3;
    let mut sorted = false;

    while gap > 1 || sorted {
        if gap > 1 {
            gap = (gap as f64 / shrink_factor) as usize;
        }

        sorted = false;

        for i in 0..nums.len() - gap {
            if nums[i] > nums[i + gap] {
                nums.swap(i, i + gap);
                sorted = true;
            }
        }
    }

    nums
}
