    let day = parts[1].parse::<u32>();
    let year = parts[2].parse::<u32>();

    if month.is_err() || day.is_err() || year.is_err() {
        return false;
    }

    let month = month.unwrap();
    let day = day.unwrap();
    let year = year.unwrap();

    if month < 1 || month > 12 {
        return false;
    }

    if day < 1 {
        return false;
    }

    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => day <= 31,
        4 | 6 | 9 | 11 => day <= 30,
        2 => day <= 29,
        _ => false,
    }
}
